To create a hexagon that changes color on hover, you can use the following HTML and JavaScript. This example uses a canvas element and the `mousemove` event to detect hover and change the color accordingly.

```html
<!DOCTYPE html>
<html>
<head>
<title>Hexagon Hover Effect</title>
<script>
function drawHexagon(ctx, x, y, size, color) {
  ctx.beginPath();
  ctx.moveTo(x, y - size);
  ctx.lineTo(x + size / 2, y - size / 2);
  ctx.lineTo(x + size, y);
  ctx.lineTo(x + size / 2, y + size / 2);
  ctx.lineTo(x, y + size);
  ctx.lineTo(x - size / 2, y + size / 2);
  ctx.lineTo(x - size, y);
  ctx.lineTo(x - size / 2, y - size / 2);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
}

function handleMouseMove(event) {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  if (isPointInHexagon(x, y)) {
    drawHexagon(ctx, 150, 150, 50, 'red');
  } else {
    drawHexagon(ctx, 150, 150, 50, 'blue');
  }
}

function isPointInHexagon(x, y) {
  const centerX = 150;
  const centerY = 150;
  const size = 50;

  const dx = x - centerX;
  const dy = y - centerY;

  const angle = Math.atan2(dy, dx);
  const distance = Math.sqrt(dx * dx + dy * dy);

  return distance <= size && angle >= -Math.PI / 6 && angle <= Math.PI / 6;
}

const canvas = document.getElementById('hexagonCanvas');
const ctx = canvas.getContext('2d');

drawHexagon(ctx, 150, 150, 50, 'blue');

canvas.addEventListener('mousemove', handleMouseMove);
</script>
</head>
<body>
<canvas id="hexagonCanvas" width="300" height="300"></canvas>
</body>
</html>
```

This code sets up a canvas and draws a hexagon. It then checks if the mouse is over the hexagon and changes its color accordingly.
